  'report.contents': 'レポートには、アプリとビルドのバージョン、OSとアーキテクチャ、時刻、コンポーネント、段階、固定エラーコード、発生回数、最大16件の固定遷移が含まれます。サニタイズ済み診断を伴う障害には、相関ID、固定の理由と例外クラス、アプリ相対のスタックフレーム、制限されたコンテキストID、HTTPステータス、検証済みプロバイダーリクエストIDも含まれます。チャット、エージェントへの指示、プロバイダーのテキスト、キー、URL、ホームパス、プロセス出力、クリップボード、ブラウザー内容、スクリーンショット、生ログ、リクエスト本文、レスポンス本文は含まれません。任意の手動説明は別扱いで、送信前に表示されます。',
  'report.retention': 'ローカルの未送信レポートは7日後に期限切れになります。受信済みレポートは受信側で30日間保持されます。ライブ送信を有効にする前に、公開済みプライバシー通知と運用者アクセス手順が必要です。',
  'report.consent': 'この選択は、このアプリセッション中、OSユーザープロファイル内のこのインストールに適用されます。有効にした後の新しい障害だけが対象です。アプリ再起動後は自動レポートがオフで始まるため、そのセッションで再度有効にしてください。オフにすると以後の自動再試行を停止し、未送信の自動レポートを削除します。すでに受信されたレポートは、この切り替えでは取り消せません。',
